'use strict';
const assert=require('assert');
const fs=require('fs');
const path=require('path');
const root=path.join(__dirname,'..');
const index=fs.readFileSync(path.join(root,'index.html'),'utf8');
const desktop=fs.readFileSync(path.join(root,'desktop.html'),'utf8');
const app=fs.readFileSync(path.join(root,'app.js'),'utf8');
const css=fs.readFileSync(path.join(root,'schedule-foundation.css'),'utf8');
const sw=fs.readFileSync(path.join(root,'service-worker.js'),'utf8');
assert(index.includes('schedule-foundation.css?v=56.0.5-schedule-card-format1'),'Desktop must load the current scheduling CSS');
assert(desktop.includes('window.location.replace'),'desktop.html must be a lightweight alias to index.html');
assert(!index.includes('data-view="capacity"'),'Capacity must not appear in main navigation');
assert(app.includes('renderSchedule=function renderSchedule()'),'One authoritative schedule renderer must be installed');
assert(app.includes('scheduleCapacityHours'),'One team/day capacity function must exist');
assert(app.includes('capacityOverrideHours'),'Optional date-specific capacity override must be supported');
assert(app.includes('schedule-top-status-v5546'),'Scheduling attention must use a compact top status area');
assert(app.includes('schedule-work-queue-v5546'),'Unscheduled work must open in the movable queue');
assert(app.includes('beginScheduleResize'),'Desktop duration resize must be supported');
assert(app.includes('scheduleCardKey'),'Keyboard duration adjustment must be supported');
assert(css.includes('border-left:3px solid var(--team-color)'),'Team colour must be a passive card accent');
assert(!css.includes('background:color-mix(in srgb,var(--team-color) 14%,white)'),'Full team-colour card backgrounds must be removed');
assert(css.includes('position:fixed!important'),'The work queue must overlay rather than compress the board');
assert(css.includes('overflow-x:auto;overflow-y:visible'),'The board may scroll horizontally but must not create a nested vertical scrollbar');
assert(sw.includes('tuinbooks-shell-v56-0-5-schedule-card-format1'),'Service worker cache must be current');
console.log('v55.4 scheduling foundation tests passed');
